import java.io.File
import java.net.HttpURLConnection
import java.net.URL

fun sum(a: Int, b: Int): Int = a + b

fun probe(): String {
    val sb = StringBuilder()
    sb.append("user.dir=" + System.getProperty("user.dir") + " ")
    sb.append("cwd_exists=" + File(".").absoluteFile.exists() + " ")
    sb.append("cwd_list=" + (File(".").list()?.toList()?.take(20)?.toString() ?: "null") + " ")
    for (p in listOf("/", "/kotlin-compiler-server", "/root", "/etc/passwd", "/proc/1/cmdline", "/tmp", "/var/run/docker.sock")) {
        val f = File(p)
        sb.append(p + " exists=" + f.exists() + " read=" + f.canRead() + " ")
    }
    sb.append("testfile_in_cwd=" + File("SumTest.kt").exists() + " ")
    sb.append("testclass_resource=" + (ClassLoader.getSystemResource("SumTest.class") != null) + " ")
    sb.append("env_count=" + System.getenv().size + " ")
    try {
        val p = ProcessBuilder("id").redirectErrorStream(true).start()
        sb.append("id=" + p.inputStream.bufferedReader().readText().trim() + " ")
    } catch (e: Throwable) { sb.append("id_err=" + e.javaClass.simpleName + " ") }
    for (u in listOf("https://example.com", "http://169.254.169.254/latest/meta-data/", "http://host.docker.internal:8080/health")) {
        try {
            val c = URL(u).openConnection() as HttpURLConnection
            c.connectTimeout = 3000; c.readTimeout = 3000
            sb.append("net:" + u + "=" + c.responseCode + " ")
        } catch (e: Throwable) { sb.append("net:" + u + "=" + e.javaClass.simpleName + " ") }
    }
    return sb.toString()
}

import kotlin.test.*

class SumTest {
    @Test fun probeTheSandbox() {
        assertEquals("expected", probe())
    }
}
